//! Behaviour of the ZIP reader on valid and hostile archives. Every archive
//! is generated by the test that uses it.

#![cfg(test)]

mod support;

use droid_archive::Limits;
use droid_archive::zip::{
    Anomaly, AnomalyKind, Component, Impact, LONG_NAME_COMPONENT_LEN, LONG_NAME_LEN, LimitKind,
    LocalField, ReadError, ZipArchive, ZipError,
};
use support::{
    EntrySpec, FLAG_ENCRYPTED, ZipBuilder, bare_central_record, crc32, into_zip64, sample,
    signing_block,
};

fn parse(data: &[u8]) -> ZipArchive<'_> {
    ZipArchive::parse(data, Limits::default()).expect("archive should open")
}

fn find<'a>(anomalies: &'a [Anomaly], code: &str) -> Vec<&'a Anomaly> {
    anomalies.iter().filter(|a| a.code() == code).collect()
}

fn has(archive: &ZipArchive<'_>, code: &str, entry: Option<usize>) -> bool {
    find(archive.anomalies(), code)
        .iter()
        .any(|a| a.entry == entry)
}

fn codes(anomalies: &[Anomaly]) -> Vec<&'static str> {
    anomalies.iter().map(Anomaly::code).collect()
}

#[test]
fn valid_archive_has_no_anomaly() {
    let mut builder = sample();
    builder.before_central_directory = signing_block();
    let data = builder.build();
    let archive = parse(&data);

    assert!(archive.anomalies().is_empty(), "{:?}", archive.anomalies());
    assert!(archive.android_accepts());
    assert_eq!(archive.entries().len(), 4);
    assert!(archive.layout().signing_block.is_some());
    assert_eq!(archive.layout().offset_shift, 0);

    let expected: [&[u8]; 4] = [
        b"<manifest/>",
        &b"dex\n035\0".repeat(200),
        b"hello hello hello",
        b"",
    ];
    for (index, content) in expected.iter().enumerate() {
        let read = archive.read(index).unwrap();
        assert_eq!(read.data, *content, "entry {index}");
        assert!(read.anomalies.is_empty(), "{:?}", read.anomalies);
    }
    assert_eq!(archive.find(b"classes.dex").map(|e| e.index), Some(1));
    let total: usize = expected.iter().map(|c| c.len()).sum();
    assert_eq!(archive.total_read(), u64::try_from(total).unwrap());
}

#[test]
fn missing_end_of_central_directory() {
    assert_eq!(
        ZipArchive::parse(b"", Limits::default()).err(),
        Some(ZipError::EocdNotFound)
    );
    assert_eq!(
        ZipArchive::parse(&[0x41; 4096], Limits::default()).err(),
        Some(ZipError::EocdNotFound)
    );
    let mut data = sample().build();
    let eocd = data.len() - 22;
    data[eocd] = b'X';
    assert_eq!(
        ZipArchive::parse(&data, Limits::default()).err(),
        Some(ZipError::EocdNotFound)
    );
}

#[test]
fn truncated_end_of_central_directory() {
    let data = sample().build();
    for cut in [1, 5, 18] {
        let truncated = &data[..data.len() - cut];
        assert_eq!(
            ZipArchive::parse(truncated, Limits::default()).err(),
            Some(ZipError::EocdTruncated),
            "cut {cut}"
        );
        assert_eq!(ZipError::EocdTruncated.code(), "zip.error.eocd_truncated");
    }
}

#[test]
fn central_directory_out_of_bounds() {
    let mut builder = sample();
    builder.eocd.cd_offset = Some(0x00FF_FFFF);
    let data = builder.build();
    assert_eq!(
        ZipArchive::parse(&data, Limits::default()).err(),
        Some(ZipError::CentralDirectoryOutOfBounds)
    );

    let mut builder = sample();
    builder.eocd.entries_total = Some(9);
    builder.eocd.entries_on_disk = Some(9);
    let data = builder.build();
    assert!(matches!(
        ZipArchive::parse(&data, Limits::default()),
        Err(ZipError::CentralDirectoryTruncated { entry: 4 })
    ));
}

#[test]
fn data_prepended_with_adjusted_offsets() {
    let mut builder = sample();
    builder.prefix = b"#!/bin/sh\nexit 0\n".to_vec();
    let data = builder.build();
    let archive = parse(&data);

    let prefix = find(archive.anomalies(), "zip.prefix_data");
    assert_eq!(prefix.len(), 1);
    assert_eq!(prefix[0].kind, AnomalyKind::PrefixData { len: 17 });
    assert_eq!(prefix[0].impact(), Impact::ArchiveRejected);
    assert!(!archive.android_accepts());
    assert!(!has(&archive, "zip.gap.unaccounted", None));
    assert_eq!(archive.read(0).unwrap().data, b"<manifest/>");
}

#[test]
fn data_prepended_without_adjusting_offsets() {
    let mut builder = sample();
    builder.prefix = vec![0xAA; 100];
    builder.offsets_include_prefix = false;
    let data = builder.build();
    let archive = parse(&data);

    assert!(archive.anomalies().contains(&Anomaly {
        kind: AnomalyKind::OffsetsShifted { delta: 100 },
        entry: None,
        component: None,
    }));
    assert!(has(&archive, "zip.prefix_data", None));
    assert_eq!(archive.layout().offset_shift, 100);
    assert!(!archive.android_accepts());
    assert_eq!(archive.read(1).unwrap().data, b"dex\n035\0".repeat(200));
}

#[test]
fn prepended_archive_hides_local_headers() {
    let mut builder = sample();
    builder.prefix = ZipBuilder::new()
        .entry(EntrySpec::stored("AndroidManifest.xml", b"decoy"))
        .build();
    let data = builder.build();
    let archive = parse(&data);
    // The prefix starts with a local header signature, which is all Android
    // checks at offset zero: it accepts the archive, and the decoy is only
    // visible to readers that follow local headers.
    assert!(!has(&archive, "zip.prefix_data", None));
    assert!(archive.android_accepts());
    assert!(has(&archive, "zip.gap.unaccounted", None));
    assert!(has(&archive, "zip.gap.hidden_local_headers", None));
}

#[test]
fn data_appended_after_the_archive() {
    let mut builder = sample();
    builder.trailer = b"appended".to_vec();
    let data = builder.build();
    let archive = parse(&data);

    let len = u64::try_from(data.len()).unwrap();
    let mismatch = find(archive.anomalies(), "zip.eocd.length_mismatch");
    assert_eq!(
        mismatch[0].kind,
        AnomalyKind::EocdLengthMismatch {
            declared_end: len - 8,
            actual_len: len
        }
    );
    assert!(!archive.android_accepts());
    assert_eq!(archive.entries().len(), 4);
}

#[test]
fn comment_containing_a_fake_end_record() {
    let inner = ZipBuilder::new().build();
    let mut builder = sample();
    builder.comment = inner;
    let data = builder.build();
    let archive = parse(&data);

    // Android selects the fake record closest to the end. It fits the end of
    // the input exactly, so the archive Android sees is empty.
    assert_eq!(archive.entries().len(), 0);
    assert!(has(&archive, "zip.empty", None));
    assert!(has(&archive, "zip.eocd.multiple_candidates", None));
}

#[test]
fn archive_comment_is_exposed() {
    let mut builder = sample();
    builder.comment = b"built by hand".to_vec();
    let data = builder.build();
    let archive = parse(&data);
    assert_eq!(archive.comment(), b"built by hand");
    assert_eq!(codes(archive.anomalies()), ["zip.eocd.comment"]);
    assert!(archive.android_accepts());
}

#[test]
fn maximal_comment_length_requires_a_zip64_locator() {
    let mut builder = sample();
    builder.comment = vec![b'c'; 0xFFFF];
    let data = builder.build();
    let archive = parse(&data);
    assert!(has(&archive, "zip.zip64.locator_missing", None));
    assert!(!archive.android_accepts());
    assert_eq!(archive.entries().len(), 4);
}

#[test]
fn zip64_archive() {
    let data = into_zip64(&sample().build());
    let archive = parse(&data);
    assert_eq!(codes(archive.anomalies()), ["zip.zip64.used"]);
    assert_eq!(
        archive.anomalies()[0].component,
        Some(Component::SigningBlock)
    );
    assert!(archive.android_accepts());
    assert!(archive.layout().zip64_eocd_offset.is_some());
    assert_eq!(archive.read(2).unwrap().data, b"hello hello hello");
}

#[test]
fn broken_zip64_locator_is_fatal() {
    let mut data = into_zip64(&sample().build());
    let locator_offset_field = data.len() - 22 - 20 + 8;
    data[locator_offset_field] ^= 0x01;
    assert_eq!(
        ZipArchive::parse(&data, Limits::default()).err(),
        Some(ZipError::Zip64Invalid)
    );
}

