#[test]
fn duplicate_names() {
    let data = sample()
        .entry(EntrySpec::stored("AndroidManifest.xml", b"<evil/>"))
        .build();
    let archive = parse(&data);
    let duplicates = find(archive.anomalies(), "zip.entry.duplicate_name");
    assert_eq!(duplicates.len(), 1);
    assert_eq!(duplicates[0].entry, Some(4));
    assert_eq!(duplicates[0].kind, AnomalyKind::DuplicateName { first: 0 });
    assert!(!archive.android_accepts());
    assert_eq!(archive.find(b"AndroidManifest.xml").unwrap().index, 0);
    assert_eq!(archive.read(4).unwrap().data, b"<evil/>");
}

#[test]
fn names_differing_by_case() {
    let data = sample()
        .entry(EntrySpec::stored("androidmanifest.XML", b"x"))
        .build();
    let archive = parse(&data);
    let found = find(archive.anomalies(), "zip.entry.case_collision");
    assert_eq!(found[0].entry, Some(4));
    assert_eq!(found[0].impact(), Impact::Informational);
    assert!(archive.android_accepts());
}

#[test]
fn zero_padding_before_the_signing_block() {
    let mut builder = sample();
    let mut padding = vec![0; 1000];
    padding.extend(signing_block());
    builder.before_central_directory = padding;
    let data = builder.build();
    let archive = parse(&data);
    let found = find(archive.anomalies(), "zip.gap.unaccounted");
    assert_eq!(found.len(), 1);
    assert!(matches!(
        found[0].kind,
        AnomalyKind::UnaccountedData {
            len: 1000,
            zero_filled: true,
            ..
        }
    ));
    assert_eq!(found[0].impact(), Impact::Informational);
    assert!(archive.layout().signing_block.is_some());
}

#[test]
fn local_header_method_differs() {
    let mut entry = EntrySpec::stored("AndroidManifest.xml", b"<manifest/>");
    entry.local.method = Some(8);
    let data = ZipBuilder::new().entry(entry).build();
    let archive = parse(&data);

    let found = find(archive.anomalies(), "zip.entry.lfh_method_mismatch");
    assert_eq!(
        found[0].kind,
        AnomalyKind::LocalMethodMismatch {
            central: 0,
            local: 8
        }
    );
    assert_eq!(found[0].impact(), Impact::Divergence);
    assert!(archive.android_accepts());
    // The central directory wins, as on Android.
    assert_eq!(archive.read(0).unwrap().data, b"<manifest/>");
}

