fn local_header_name_differs() {
    let mut entry = EntrySpec::stored("AndroidManifest.xml", b"<manifest/>");
    entry.local.name = Some(b"AndroidManifest.xmI".to_vec());
    let data = ZipBuilder::new().entry(entry).build();
    let archive = parse(&data);
    let found = find(archive.anomalies(), "zip.entry.lfh_name_mismatch");
    assert_eq!(found[0].impact(), Impact::EntryRejected);
    assert!(archive.android_accepts());
}

#[test]
fn local_header_sizes_differ() {
    let mut entry = EntrySpec::deflated("classes.dex", &[7u8; 300]);
    entry.local.uncompressed_size = Some(10);
    entry.local.crc32 = Some(1);
    let data = ZipBuilder::new().entry(entry).build();
    let archive = parse(&data);
    let found = find(archive.anomalies(), "zip.entry.lfh_value_mismatch");
    let kinds: Vec<_> = found.iter().map(|a| a.kind.clone()).collect();
    assert_eq!(
        kinds,
        [
            AnomalyKind::LocalValueMismatch {
                field: LocalField::Crc32,
                data_descriptor: false
            },
            AnomalyKind::LocalValueMismatch {
                field: LocalField::UncompressedSize,
                data_descriptor: false
            },
        ]
    );
    assert!(found.iter().all(|a| a.impact() == Impact::EntryRejected));
}

