#[test]
fn data_after_the_deflate_stream() {
    let mut entry = EntrySpec::deflated("a", b"some content to compress");
    entry.payload.extend_from_slice(b"JUNK");
    entry.compressed_size += 4;
    let data = ZipBuilder::new().entry(entry).build();
    let archive = parse(&data);
    let read = archive.read(0).unwrap();
    assert_eq!(read.data, b"some content to compress");
    assert_eq!(
        read.anomalies[0].kind,
        AnomalyKind::DeflateTrailingData { len: 4 }
    );
}

#[test]
fn crc_mismatch_is_reported_but_ignored() {
    let mut entry = EntrySpec::stored("a", b"payload");
    entry.crc32 = 0x1234_5678;
    let data = ZipBuilder::new().entry(entry).build();
    let archive = parse(&data);
    assert!(archive.anomalies().is_empty());
    let read = archive.read(0).unwrap();
    assert_eq!(read.data, b"payload");
    assert_eq!(
        read.anomalies[0].kind,
        AnomalyKind::CrcMismatch {
            declared: 0x1234_5678,
            actual: crc32(b"payload")
        }
    );
    assert_eq!(read.anomalies[0].impact(), Impact::Divergence);
}

#[test]
fn data_descriptor_mismatch() {
    let mut builder = ZipBuilder::new();
    for name in ["classes.dex", "res/raw/a.bin"] {
        let mut entry = EntrySpec::deflated(name, b"aaaa").with_data_descriptor(true);
        let last = entry.data_descriptor.len() - 1;
        entry.data_descriptor[last] = 0x7F;
        builder = builder.entry(entry);
    }
    let data = builder.build();
    let archive = parse(&data);
    let dex = archive.read(0).unwrap();
    assert_eq!(
        codes(&dex.anomalies),
        ["zip.entry.data_descriptor_mismatch"]
    );
    assert_eq!(dex.anomalies[0].component, Some(Component::Dex));
    assert_eq!(dex.anomalies[0].impact(), Impact::EntryRejected);
    // The resource loader does not check data descriptors.
    let resource = archive.read(1).unwrap();
    assert_eq!(resource.anomalies[0].component, Some(Component::Resources));
    assert_eq!(resource.anomalies[0].impact(), Impact::Divergence);
}

#[test]
fn hostile_paths() {
    let names = [
        "../../data/system/evil",
        "/system/bin/sh",
        "C:\\Windows\\evil.dll",
        "assets\\..\\..\\evil",
        "",
    ];
    let mut builder = ZipBuilder::new();
    for name in names {
        builder = builder.entry(EntrySpec::stored(name, b"x"));
    }
    let data = builder.build();
    let archive = parse(&data);
    assert!(has(&archive, "zip.entry.path_traversal", Some(0)));
    assert!(has(&archive, "zip.entry.absolute_path", Some(1)));
    assert!(has(&archive, "zip.entry.absolute_path", Some(2)));
    assert!(has(&archive, "zip.entry.backslash", Some(2)));
    assert!(has(&archive, "zip.entry.path_traversal", Some(3)));
    assert!(has(&archive, "zip.entry.backslash", Some(3)));
    assert!(has(&archive, "zip.entry.empty_name", Some(4)));
    // Android does not check paths.
    assert!(archive.android_accepts());
    assert_eq!(archive.read(0).unwrap().data, b"x");
}

#[test]
fn symbolic_link() {
    let mut entry = EntrySpec::stored("lib/arm64-v8a/libfoo.so", b"/data/data/x");
    entry.external_attributes = 0o120_777 << 16;
    let data = ZipBuilder::new().entry(entry).build();
    let archive = parse(&data);
    assert!(archive.entries()[0].is_symlink());
    assert!(has(&archive, "zip.entry.symlink", Some(0)));
    assert_eq!(archive.read(0).unwrap().data, b"/data/data/x");
}

#[test]
fn invalid_and_lax_utf8_names() {
    let data = ZipBuilder::new()
        .entry(EntrySpec::stored("x", b"1").with_name_bytes(b"a\0b"))
        .entry(EntrySpec::stored("x", b"2").with_name_bytes(&[b'a', 0xC0, 0xAF]))
        .build();
    let archive = parse(&data);
    assert!(has(&archive, "zip.entry.invalid_name", Some(0)));
    assert!(has(&archive, "zip.entry.name_not_utf8", Some(1)));
    assert!(!has(&archive, "zip.entry.invalid_name", Some(1)));
    assert!(!archive.android_accepts());
    assert_eq!(archive.entries()[1].name_str(), None);
}

