#[test]
fn overlapping_entries() {
    let inner = EntrySpec::stored("inner", b"shared");
    let inner_archive = ZipBuilder::new().entry(inner.clone()).build();
    let inner_local = &inner_archive[..30 + 5 + 6];
    let outer = EntrySpec::stored("o", inner_local);
    let mut shadow = inner;
    shadow.central_only = true;
    shadow.local_header_offset = Some(30 + 1);
    let data = ZipBuilder::new().entry(outer).entry(shadow).build();
    let archive = parse(&data);
    assert!(archive.anomalies().contains(&Anomaly {
        kind: AnomalyKind::Overlap { other: 0 },
        entry: Some(1),
        component: Some(Component::Resources),
    }));
    assert_eq!(archive.read(1).unwrap().data, b"shared");
}

#[test]
fn blocking_limits_at_open() {
    let data = sample().build();
    let limits = Limits {
        max_entries: 3,
        ..Limits::default()
    };
    assert_eq!(
        ZipArchive::parse(&data, limits).err(),
        Some(ZipError::LimitExceeded {
            limit: LimitKind::Entries,
            value: 4,
            max: 3
        })
    );
    let cd_size = parse(&data).layout().central_directory_size;
    let limits = Limits {
        max_central_directory_size: cd_size - 1,
        ..Limits::default()
    };
    assert_eq!(
        ZipArchive::parse(&data, limits).err(),
        Some(ZipError::LimitExceeded {
            limit: LimitKind::CentralDirectorySize,
            value: cd_size,
            max: cd_size - 1
        })
    );
}

#[test]
fn long_names_are_reported_not_refused() {
    let longest = "a".repeat(65_535);
    let long_path = format!("lib/arm64-v8a/{}", "x/".repeat(2100));
    let long_component = format!("assets/{}.bin", "b".repeat(300));
    let names = [
        "res/raw/".to_string() + &"c".repeat(200),
        long_path.clone(),
        long_component.clone(),
        longest.clone(),
    ];
    let mut builder = ZipBuilder::new();
    for name in &names {
        builder = builder.entry(EntrySpec::stored(name, b"x"));
    }
    let data = builder.build();
    let archive = parse(&data);

    assert!(!has(&archive, "zip.entry.long_name", Some(0)));
    let found = find(archive.anomalies(), "zip.entry.long_name");
    let reported: Vec<_> = found.iter().map(|a| (a.entry, a.kind.clone())).collect();
    assert_eq!(
        reported,
        [
            (
                Some(1),
                AnomalyKind::LongName {
                    len: u64::try_from(long_path.len()).unwrap(),
                    longest_component: 9
                }
            ),
            (
                Some(2),
                AnomalyKind::LongName {
                    len: u64::try_from(long_component.len()).unwrap(),
                    longest_component: 304
                }
            ),
            (
                Some(3),
                AnomalyKind::LongName {
                    len: 65_535,
                    longest_component: 65_535
                }
            ),
        ]
    );
    assert!(found.iter().all(|a| a.impact() == Impact::Suspicious));
    assert!(archive.android_accepts());
    for index in 0..names.len() {
        assert_eq!(archive.read(index).unwrap().data, b"x");
    }
    assert_eq!(archive.entries()[3].name.len(), 65_535);
    assert_eq!(LONG_NAME_LEN, 4096);
    assert_eq!(LONG_NAME_COMPONENT_LEN, 255);
}

fn dex_archive(names: &[&str]) -> Vec<u8> {
    let mut builder = ZipBuilder::new().entry(EntrySpec::stored("AndroidManifest.xml", b"<m/>"));
    for name in names {
        builder = builder.entry(EntrySpec::deflated(name, b"dex\n035\0"));
    }
    builder.build()
}

fn unreachable_dex(archive: &ZipArchive<'_>) -> Vec<(String, u64)> {
    find(archive.anomalies(), "zip.entry.dex_unreachable")
        .iter()
        .map(|anomaly| {
            let index = anomaly.entry.unwrap();
            assert_eq!(anomaly.component, Some(Component::Dex));
            assert_eq!(anomaly.impact(), Impact::Suspicious);
            let AnomalyKind::DexUnreachable { missing } = anomaly.kind else {
                panic!("unexpected kind {:?}", anomaly.kind);
            };
            (archive.entries()[index].name_lossy().into_owned(), missing)
        })
        .collect()
}

#[test]
fn contiguous_dex_entries_are_all_loaded() {
    let data = dex_archive(&["classes3.dex", "classes.dex", "classes2.dex"]);
    let archive = parse(&data);
    assert!(unreachable_dex(&archive).is_empty());
    assert!(archive.anomalies().is_empty(), "{:?}", archive.anomalies());
}

#[test]
fn dex_entries_after_a_gap_are_never_loaded() {
    let data = dex_archive(&["classes.dex", "classes3.dex"]);
    let archive = parse(&data);
    assert_eq!(unreachable_dex(&archive), [("classes3.dex".to_string(), 2)]);
    // ART skips the entry silently: the archive installs and runs.
    assert!(archive.android_accepts());
    let anomaly = find(archive.anomalies(), "zip.entry.dex_unreachable")[0];
    assert_eq!(
        anomaly.to_string(),
        "[zip.entry.dex_unreachable] entry 2: (dex) never loaded by ART, \
         which stops at the missing classes2.dex"
    );

    let data = dex_archive(&[
        "classes.dex",
        "classes2.dex",
        "classes4.dex",
        "classes5.dex",
        "classes10.dex",
    ]);
    let archive = parse(&data);
    assert_eq!(
        unreachable_dex(&archive),
        [
            ("classes4.dex".to_string(), 3),
            ("classes5.dex".to_string(), 3),
            ("classes10.dex".to_string(), 3),
        ]
    );
}

#[test]
fn no_dex_is_loaded_without_classes_dex() {
    let data = dex_archive(&["classes2.dex", "classes3.dex"]);
    let archive = parse(&data);
    assert_eq!(
        unreachable_dex(&archive),
        [
            ("classes2.dex".to_string(), 1),
            ("classes3.dex".to_string(), 1),
        ]
    );
}

#[test]
fn only_art_names_fill_the_dex_sequence() {
    // `classes1.dex`, `classes02.dex` and DEX files outside the root are not
    // ART names: they do not fill the gap before `classes3.dex`.
    let data = dex_archive(&[
        "classes.dex",
        "classes1.dex",
        "classes02.dex",
        "assets/classes2.dex",
        "Classes2.dex",
        "classes3.dex",
        "classes99999999999999999999999.dex",
    ]);
    let archive = parse(&data);
    assert_eq!(
        unreachable_dex(&archive),
        [
            ("classes3.dex".to_string(), 2),
            ("classes99999999999999999999999.dex".to_string(), 2),
        ]
    );
}

#[test]
fn codes_are_stable() {
    let kinds = [
        (
            AnomalyKind::EmptyArchive,
            "zip.empty",
            Impact::ArchiveRejected,
        ),
        (
            AnomalyKind::UnsupportedMethod { method: 99 },
            "zip.entry.unsupported_method",
            Impact::Divergence,
        ),
        (
            AnomalyKind::PathTraversal,
            "zip.entry.path_traversal",
            Impact::Suspicious,
        ),
        (
            AnomalyKind::EocdComment { len: 1 },
            "zip.eocd.comment",
            Impact::Informational,
        ),
        (
            AnomalyKind::DexUnreachable { missing: 2 },
            "zip.entry.dex_unreachable",
            Impact::Suspicious,
        ),
    ];
    for (kind, code, impact) in kinds {
        assert_eq!(kind.code(), code);
        assert_eq!(kind.impact_in(None), impact);
        assert!(!kind.to_string().is_empty());
    }
    assert_eq!(ReadError::InvalidDeflate.code(), "zip.read.invalid_deflate");
    assert_eq!(Impact::Divergence.code(), "divergence");
    assert_eq!(Component::NativeLibraries.code(), "native_libraries");
    let anomaly = AnomalyKind::UnsupportedMethod { method: 99 };
    assert_eq!(
        anomaly.impact_in(Some(Component::Dex)),
        Impact::EntryRejected
    );
    assert_eq!(
        anomaly.impact_in(Some(Component::Resources)),
        Impact::Divergence
    );
}
